export const levels = ['error', 'warn', 'info', 'debug'] as const
export const services = ['api', 'auth', 'billing', 'worker', 'edge'] as const
export const statusClasses = ['2xx', '3xx', '4xx', '5xx'] as const

export type LogLevel = (typeof levels)[number]
export type Service = (typeof services)[number]
export type StatusClass = (typeof statusClasses)[number]

export type LogEntry = {
  id: string
  /** Epoch ms */
  timestamp: number
  level: LogLevel
  service: Service
  method: 'GET' | 'POST' | 'PUT' | 'DELETE'
  path: string
  status: number
  durationMs: number
  message: string
  requestId: string
  region: string
}

// Fixed "now" so relative times render the same on server and client.
export const NOW = Date.UTC(2026, 8, 23, 14, 0, 0)

// Small deterministic PRNG, so the demo data never changes between renders.
function mulberry32(seed: number) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const random = mulberry32(11)
const pick = <T>(items: readonly T[]) =>
  items[Math.floor(random() * items.length)]

const routes: Record<Service, { method: LogEntry['method']; path: string }[]> =
  {
    api: [
      { method: 'GET', path: '/v1/projects' },
      { method: 'GET', path: '/v1/projects/:id' },
      { method: 'POST', path: '/v1/projects' },
      { method: 'DELETE', path: '/v1/projects/:id' },
    ],
    auth: [
      { method: 'POST', path: '/auth/login' },
      { method: 'POST', path: '/auth/refresh' },
      { method: 'GET', path: '/auth/callback' },
    ],
    billing: [
      { method: 'POST', path: '/billing/checkout' },
      { method: 'GET', path: '/billing/invoices' },
      { method: 'POST', path: '/billing/webhook' },
    ],
    worker: [
      { method: 'POST', path: '/jobs/email' },
      { method: 'POST', path: '/jobs/thumbnail' },
    ],
    edge: [
      { method: 'GET', path: '/' },
      { method: 'GET', path: '/pricing' },
      { method: 'GET', path: '/assets/app.js' },
    ],
  }

const messages: Record<LogLevel, readonly string[]> = {
  error: [
    'Upstream timed out after 10000ms',
    'Stripe webhook signature mismatch',
    'Connection pool exhausted (max=20)',
    'Unhandled rejection: ECONNRESET',
  ],
  warn: [
    'Rate limit reached for token',
    'Invalid refresh token',
    'Validation failed: name is required',
    'Slow query: 1843ms on projects_by_owner',
  ],
  info: [
    'Request completed',
    'User signed in',
    'Invoice generated',
    'Cache hit',
    'Job finished',
  ],
  debug: [
    'Retrying job (attempt 2 of 5)',
    'Feature flag new-pricing evaluated to false',
    'Cache miss, fetching from origin',
  ],
}

const regions = ['iad1', 'fra1', 'sfo1', 'hnd1']

function hex(length: number) {
  return Array.from({ length }, () =>
    Math.floor(random() * 16).toString(16),
  ).join('')
}

function levelFor(service: Service): LogLevel {
  const roll = random()
  if (roll < 0.1) return 'error'
  if (roll < 0.26) return 'warn'
  // Workers are chatty at debug level; request handlers mostly aren't
  if (roll < (service === 'worker' ? 0.6 : 0.36)) return 'debug'
  return 'info'
}

function statusFor(level: LogLevel, method: LogEntry['method']): number {
  if (level === 'error') return pick([500, 502, 503, 504])
  if (level === 'warn') return pick([400, 401, 404, 422, 429])
  if (method === 'POST') return 201
  return random() < 0.15 ? 304 : 200
}

const HOUR = 3_600_000

let msAgo = 1_200
export const logs: LogEntry[] = Array.from({ length: 80 }, (_, i) => {
  const service = pick(services)
  const route = pick(routes[service])
  const level = levelFor(service)
  const entry: LogEntry = {
    id: `log_${hex(12)}`,
    timestamp: NOW - msAgo,
    level,
    service,
    method: route.method,
    path: route.path,
    status: statusFor(level, route.method),
    durationMs:
      level === 'error'
        ? Math.floor(2_000 + random() * 8_000)
        : Math.floor(4 + random() * 380),
    message: pick(messages[level]),
    requestId: `req_${hex(8)}`,
    region: pick(regions),
  }
  // Gaps grow with age, so recent events are dense and the list spans ~2 weeks
  msAgo += Math.floor((random() * 2 + i * 0.07) * HOUR)
  return entry
})

export function toStatusClass(status: number): StatusClass {
  return `${Math.floor(status / 100)}xx` as StatusClass
}

const months = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
]
const pad = (n: number) => String(n).padStart(2, '0')

/** "Sep 23" in UTC, so server and client render the same string */
export function formatDay(timestamp: number): string {
  const d = new Date(timestamp)
  return `${months[d.getUTCMonth()]} ${d.getUTCDate()}`
}

/** "13:59:58" in UTC */
export function formatTime(timestamp: number): string {
  const d = new Date(timestamp)
  return `${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`
}

export function formatDuration(ms: number): string {
  return ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(2)}s`
}

'use client'

import type { ColumnDef, FilterFn } from '@tanstack/react-table'
import type { DateRange } from 'react-day-picker'
import { cn } from '#/lib/utils.ts'
import { formatDay, formatTime, toStatusClass } from './data'
import type { LogEntry, LogLevel } from './data'
import { utcDayStart } from './date-range-filter'

const levelStyles: Record<LogLevel, { dot: string; text: string }> = {
  error: { dot: 'bg-red-500', text: 'text-red-600 dark:text-red-400' },
  warn: { dot: 'bg-amber-500', text: 'text-amber-600 dark:text-amber-400' },
  info: { dot: 'bg-sky-500', text: 'text-sky-600 dark:text-sky-400' },
  debug: { dot: 'bg-muted-foreground/40', text: 'text-muted-foreground' },
}

/** Level marker, shared by the table and the Level filter menu */
export function LevelDot({ level }: { level: LogLevel }) {
  return (
    <span
      aria-hidden
      className={cn('size-1.5 shrink-0 rounded-full', levelStyles[level].dot)}
    />
  )
}

export function LevelLabel({ level }: { level: LogLevel }) {
  return (
    <span
      className={cn(
        'flex items-center gap-2 font-medium capitalize',
        levelStyles[level].text,
      )}
    >
      <LevelDot level={level} />
      {level}
    </span>
  )
}

export function statusTone(status: number) {
  if (status >= 500) return 'text-red-600 dark:text-red-400'
  if (status >= 400) return 'text-amber-600 dark:text-amber-400'
  return 'text-muted-foreground'
}

/** Wraps every case-insensitive match of `query` in a <mark> */
function Highlight({ text, query }: { text: string; query: string }) {
  const q = query.trim()
  if (!q) return text
  const parts = text.split(
    new RegExp(`(${q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi'),
  )
  return parts.map((part, i) =>
    i % 2 === 1 ? (
      <mark
        key={i}
        className="rounded-[2px] bg-yellow-300/60 text-foreground dark:bg-yellow-500/40"
      >
        {part}
      </mark>
    ) : (
      part
    ),
  )
}

// Multi-select filters store string[]; an empty/undefined value means "all"
const inList: FilterFn<LogEntry> = (row, id, value: string[] | undefined) =>
  !value?.length || value.includes(row.getValue<string>(id))

// Both ends of the range are whole days, inclusive
const inDateRange: FilterFn<LogEntry> = (
  row,
  id,
  range: DateRange | undefined,
) => {
  if (!range?.from) return true
  const timestamp = row.getValue<number>(id)
  const start = utcDayStart(range.from)
  const end = utcDayStart(range.to ?? range.from) + 86_400_000
  return timestamp >= start && timestamp < end
}

export const columns: ColumnDef<LogEntry>[] = [
  {
    accessorKey: 'timestamp',
    header: 'Time (UTC)',
    filterFn: inDateRange,
    cell: ({ row }) => (
      <span className="whitespace-nowrap tabular-nums">
        <span className="text-muted-foreground">
          {formatDay(row.original.timestamp)}
        </span>{' '}
        {formatTime(row.original.timestamp)}
      </span>
    ),
  },
  {
    accessorKey: 'level',
    header: 'Level',
    filterFn: inList,
    cell: ({ row }) => <LevelLabel level={row.original.level} />,
  },
  {
    accessorKey: 'service',
    header: 'Service',
    filterFn: inList,
  },
  {
    id: 'statusClass',
    accessorFn: (row) => toStatusClass(row.status),
    header: 'Request',
    filterFn: inList,
    cell: ({ row, table }) => {
      const log = row.original
      const query = table.getState().globalFilter as string
      return (
        <span className="flex items-center gap-2 whitespace-nowrap">
          <span
            className={cn('font-medium tabular-nums', statusTone(log.status))}
          >
            {log.status}
          </span>
          <span className="text-xs font-medium text-muted-foreground">
            {log.method}
          </span>
          <span>
            <Highlight text={log.path} query={query} />
          </span>
        </span>
      )
    },
  },
  {
    accessorKey: 'message',
    header: 'Message',
    cell: ({ row, table }) => (
      <span className="block truncate">
        <Highlight
          text={row.original.message}
          query={table.getState().globalFilter as string}
        />
      </span>
    ),
  },
]

'use client'

import {
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { FilterFn, TableOptions } from '@tanstack/react-table'
import type { LogEntry } from './data'

export const PAGE_SIZE = 20

// Search matches what people paste from an alert: message, path, or a request id
const searchLogs: FilterFn<LogEntry> = (row, _id, query: string) => {
  const q = query.trim().toLowerCase()
  if (!q) return true
  const log = row.original
  return [log.message, log.path, log.requestId].some((field) =>
    field.toLowerCase().includes(q),
  )
}

type LogsTableOptions = Pick<TableOptions<LogEntry>, 'data' | 'columns'> &
  Partial<Omit<TableOptions<LogEntry>, 'data' | 'columns'>>

/**
 * Filtering, faceting, search, and paging shared by both logs layouts. Each
 * layout adds its own options on top: row expansion, or a selected row.
 */
export function useLogsTable(options: LogsTableOptions) {
  return useReactTable({
    getRowId: (row) => row.id,
    globalFilterFn: searchLogs,
    initialState: {
      globalFilter: '',
      pagination: { pageIndex: 0, pageSize: PAGE_SIZE },
    },
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
    getPaginationRowModel: getPaginationRowModel(),
    ...options,
  })
}

import { Fragment } from 'react'
import { cn } from '#/lib/utils.ts'
import { formatDuration } from './data'
import type { LogEntry } from './data'

function fieldsOf(log: LogEntry): [string, string][] {
  return [
    ['Timestamp', new Date(log.timestamp).toISOString()],
    ['Request ID', log.requestId],
    ['Level', log.level],
    ['Service', log.service],
    ['Region', log.region],
    ['Method', log.method],
    ['Path', log.path],
    ['Status', String(log.status)],
    ['Duration', formatDuration(log.durationMs)],
    ['Message', log.message],
  ]
}

interface LogFieldsProps {
  log: LogEntry
  /** Labels to leave out, when the surrounding layout already shows them */
  omit?: string[]
  className?: string
}

/** Every field of an event, including ones that are not table columns */
export function LogFields({ log, omit = [], className }: LogFieldsProps) {
  return (
    <dl
      className={cn(
        'grid grid-cols-[max-content_1fr] gap-x-6 gap-y-1.5 text-sm whitespace-normal',
        className,
      )}
    >
      {fieldsOf(log)
        .filter(([label]) => !omit.includes(label))
        .map(([label, value]) => (
          <Fragment key={label}>
            <dt className="text-muted-foreground">{label}</dt>
            <dd className="break-all">{value}</dd>
          </Fragment>
        ))}
    </dl>
  )
}

'use client'

import { Check, PlusCircle } from 'lucide-react'
import type { Column } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { Button } from '#/components/ui/button'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '#/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'
import { cn } from '#/lib/utils.ts'

interface FacetedFilterProps<TData> {
  column: Column<TData> | undefined
  title: string
  options: readonly string[]
  /** Optional marker drawn before each option, e.g. a status dot */
  renderIcon?: (value: string) => React.ReactNode
  /** Display text for an option, when it differs from the stored value */
  formatLabel?: (value: string) => string
}

/**
 * Multi-select column filter. Counts come from TanStack's faceting, which
 * applies every *other* active filter, so they always add up to what you'd
 * see after ticking that option.
 */
export function FacetedFilter<TData>({
  column,
  title,
  options,
  renderIcon,
  formatLabel = (value) => value,
}: FacetedFilterProps<TData>) {
  const counts = column?.getFacetedUniqueValues()
  const selected = new Set(
    (column?.getFilterValue() as string[] | undefined) ?? [],
  )

  function toggle(value: string) {
    const next = new Set(selected)
    if (next.has(value)) next.delete(value)
    else next.add(value)
    column?.setFilterValue(next.size ? [...next] : undefined)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm" className="h-8 border-dashed">
          <PlusCircle className="size-3.5" />
          {title}
          {selected.size > 0 && (
            <>
              <span className="mx-0.5 h-4 w-px bg-border" />
              {selected.size > 2 ? (
                <Badge
                  variant="secondary"
                  className="rounded-sm px-1 font-normal"
                >
                  {selected.size} selected
                </Badge>
              ) : (
                [...selected].map((value) => (
                  <Badge
                    key={value}
                    variant="secondary"
                    className="rounded-sm px-1 font-normal"
                  >
                    {formatLabel(value)}
                  </Badge>
                ))
              )}
            </>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-0" align="end">
        <Command>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandEmpty>No results.</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selected.has(option)
                return (
                  <CommandItem key={option} onSelect={() => toggle(option)}>
                    <span
                      className={cn(
                        'flex size-4 items-center justify-center rounded-[4px] border',
                        isSelected
                          ? 'border-primary bg-primary text-primary-foreground'
                          : 'opacity-50',
                      )}
                    >
                      {isSelected && <Check className="size-3" />}
                    </span>
                    {renderIcon?.(option)}
                    <span className="truncate">{formatLabel(option)}</span>
                    <span className="ml-auto text-xs text-muted-foreground tabular-nums">
                      {counts?.get(option) ?? 0}
                    </span>
                  </CommandItem>
                )
              })}
            </CommandGroup>
            {selected.size > 0 && (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem
                    onSelect={() => column?.setFilterValue(undefined)}
                    className="justify-center text-center"
                  >
                    Clear filter
                  </CommandItem>
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useState } from 'react'
import { CalendarIcon } from 'lucide-react'
import type { Column } from '@tanstack/react-table'
import type { DateRange } from 'react-day-picker'

import { Button } from '#/components/ui/button'
import { Calendar } from '#/components/ui/calendar'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'
import { cn } from '#/lib/utils.ts'
import { NOW, formatDay } from './data'

const DAY = 86_400_000

/**
 * The calendar hands back local midnight for the picked day. Logs are shown
 * in UTC, so read the picked calendar date as a UTC day rather than shifting
 * it by the viewer's offset.
 */
export function utcDayStart(date: Date) {
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate())
}

/** The calendar works in local dates; build one that shows the given UTC day */
function calendarDate(timestamp: number) {
  const d = new Date(timestamp)
  return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())
}

function formatRange(from: Date, to: Date) {
  const start = formatDay(utcDayStart(from))
  const end = formatDay(utcDayStart(to))
  return start === end ? start : `${start} – ${end}`
}

const presets = [
  { label: 'Today', days: 1 },
  { label: 'Last 3 days', days: 3 },
  { label: 'Last 7 days', days: 7 },
  { label: 'Last 14 days', days: 14 },
]

interface DateRangeFilterProps<TData> {
  column: Column<TData> | undefined
}

export function DateRangeFilter<TData>({
  column,
}: DateRangeFilterProps<TData>) {
  const value = column?.getFilterValue() as DateRange | undefined
  const [open, setOpen] = useState(false)
  // The range being picked; it only becomes the filter once both ends are set
  const [draft, setDraft] = useState<DateRange | undefined>(value)
  const today = calendarDate(NOW)

  function apply(range: DateRange | undefined) {
    column?.setFilterValue(range)
    setDraft(range)
    setOpen(false)
  }

  // react-day-picker's own range logic turns the first click into a one-day
  // range and later clicks only move an end, so a new range can never be
  // started. Pick start, then end, explicitly instead.
  function pickDay(day: Date) {
    if (!draft?.from || draft.to) {
      setDraft({ from: day, to: undefined })
      return
    }
    apply(
      day < draft.from
        ? { from: day, to: draft.from }
        : { from: draft.from, to: day },
    )
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next)
        // Reopening shows the applied range, not a half-picked leftover
        if (next) setDraft(value)
      }}
    >
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn('h-8 font-normal', !value && 'border-dashed')}
        >
          <CalendarIcon className="size-3.5" />
          {value?.from && value.to
            ? formatRange(value.from, value.to)
            : 'Date range'}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="flex w-auto flex-col p-0 sm:flex-row"
        align="end"
      >
        <div className="flex flex-wrap gap-0.5 border-b p-2 sm:w-32 sm:flex-col sm:border-r sm:border-b-0">
          {presets.map((preset) => (
            <Button
              key={preset.label}
              variant="ghost"
              size="sm"
              className="justify-start font-normal"
              onClick={() =>
                apply({
                  from: calendarDate(NOW - (preset.days - 1) * DAY),
                  to: today,
                })
              }
            >
              {preset.label}
            </Button>
          ))}
        </div>
        <div>
          <Calendar
            mode="range"
            numberOfMonths={2}
            defaultMonth={calendarDate(NOW - 30 * DAY)}
            selected={draft}
            onSelect={(_, day) => pickDay(day)}
            today={today}
            disabled={{ after: today }}
          />
          <div className="flex items-center gap-2 border-t px-3 py-2">
            <p className="text-sm text-muted-foreground tabular-nums">
              {!draft?.from
                ? 'Pick a start date'
                : !draft.to
                  ? `${formatDay(utcDayStart(draft.from))} – pick an end date`
                  : formatRange(draft.from, draft.to)}
            </p>
            {value && (
              <Button
                variant="ghost"
                size="sm"
                className="ml-auto h-7 font-normal"
                onClick={() => apply(undefined)}
              >
                Clear
              </Button>
            )}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import type { Table } from '@tanstack/react-table'
import { Search, X } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { Input } from '#/components/ui/input'
import { LevelDot } from './columns'
import { levels, services, statusClasses } from './data'
import type { LogEntry, LogLevel } from './data'
import { DateRangeFilter } from './date-range-filter'
import { FacetedFilter } from './faceted-filter'
import { PAGE_SIZE } from './use-logs-table'

export function isFiltered(table: Table<LogEntry>) {
  const { columnFilters, globalFilter } = table.getState()
  return columnFilters.length > 0 || globalFilter !== ''
}

export function clearFilters(table: Table<LogEntry>) {
  table.resetColumnFilters(true)
  table.setGlobalFilter('')
}

export function LogsToolbar({ table }: { table: Table<LogEntry> }) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <div className="relative w-full sm:w-auto sm:max-w-64 sm:min-w-40 sm:flex-1">
        <Search className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground" />
        <Input
          value={table.getState().globalFilter as string}
          onChange={(e) => table.setGlobalFilter(e.target.value)}
          placeholder="Message, path, request id…"
          aria-label="Search logs"
          className="h-8 pl-8"
        />
      </div>
      <div className="flex flex-wrap items-center gap-2 sm:ml-auto sm:justify-end">
        {isFiltered(table) && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8 px-2"
            onClick={() => clearFilters(table)}
          >
            Reset
            <X className="size-3.5" />
          </Button>
        )}
        <DateRangeFilter column={table.getColumn('timestamp')} />
        <FacetedFilter
          column={table.getColumn('level')}
          title="Level"
          options={levels}
          renderIcon={(level) => <LevelDot level={level as LogLevel} />}
          formatLabel={(level) => level[0].toUpperCase() + level.slice(1)}
        />
        <FacetedFilter
          column={table.getColumn('service')}
          title="Service"
          options={services}
        />
        <FacetedFilter
          column={table.getColumn('statusClass')}
          title="Status"
          options={statusClasses}
        />
      </div>
    </div>
  )
}

/** Grows the page instead of paging, so newest events stay on top */
export function LoadOlderEvents({ table }: { table: Table<LogEntry> }) {
  const filteredCount = table.getFilteredRowModel().rows.length
  const shownCount = table.getRowModel().rows.length
  if (shownCount >= filteredCount) return null
  return (
    <div className="flex items-center justify-center gap-3">
      <p className="text-sm text-muted-foreground tabular-nums">
        Showing {shownCount} of {filteredCount}
      </p>
      <Button
        type="button"
        variant="outline"
        size="sm"
        className="h-8"
        onClick={() => table.setPageSize((size) => size + PAGE_SIZE)}
      >
        Load older events
      </Button>
    </div>
  )
}

export function NoResults({ table }: { table: Table<LogEntry> }) {
  return (
    <>
      <p className="text-muted-foreground">
        No log events match these filters.
      </p>
      <Button
        type="button"
        variant="link"
        size="sm"
        onClick={() => clearFilters(table)}
      >
        Reset filters
      </Button>
    </>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { flexRender } from '@tanstack/react-table'
import type { ColumnDef, Row } from '@tanstack/react-table'
import { ChevronDown, ChevronUp, X } from 'lucide-react'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils.ts'
import { LevelLabel, statusTone } from './columns'
import { formatDay, formatTime } from './data'
import type { LogEntry } from './data'
import { LogFields } from './log-fields'
import { LoadOlderEvents, LogsToolbar, NoResults } from './toolbar'
import { useLogsTable } from './use-logs-table'

// The panel takes the room these columns would use; its header repeats them
const hiddenWhileOpen = { service: false, statusClass: false }

interface LogsSidePanelTableProps {
  columns: ColumnDef<LogEntry, any>[]
  data: LogEntry[]
}

export function LogsSidePanelTable({ columns, data }: LogsSidePanelTableProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const table = useLogsTable({
    data,
    columns,
    state: { columnVisibility: selectedId ? hiddenWhileOpen : {} },
  })

  const rows = table.getRowModel().rows
  const selectedIndex = rows.findIndex((row) => row.id === selectedId)
  const selected = selectedIndex === -1 ? undefined : rows[selectedIndex]

  // A filter can remove the selected event; close the panel instead of
  // showing details for a row that is no longer in the table
  useEffect(() => {
    if (selectedId && !selected) setSelectedId(null)
  }, [selectedId, selected])

  function selectAt(index: number) {
    const row = rows.at(index)
    if (index < 0 || !row) return
    setSelectedId(row.id)
    document.getElementById(`log-row-${row.id}`)?.focus()
  }

  function onRowKeyDown(e: React.KeyboardEvent, index: number) {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault()
      selectAt(index + (e.key === 'ArrowDown' ? 1 : -1))
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      setSelectedId(rows[index].id === selectedId ? null : rows[index].id)
    } else if (e.key === 'Escape') {
      setSelectedId(null)
    }
  }

  return (
    <div className="space-y-3">
      <LogsToolbar table={table} />

      {/* overflow-clip (not hidden) keeps the rounded corners without
          breaking the panel's sticky positioning */}
      <div className="relative flex overflow-clip rounded-md border">
        <div className="min-w-0 flex-1">
          <Table>
            <TableHeader>
              {table.getHeaderGroups().map((headerGroup) => (
                <TableRow key={headerGroup.id}>
                  {headerGroup.headers.map((header) => (
                    <TableHead
                      key={header.id}
                      className={cn(
                        'h-9 text-xs',
                        header.column.id === 'message' && 'w-full',
                      )}
                    >
                      {flexRender(
                        header.column.columnDef.header,
                        header.getContext(),
                      )}
                    </TableHead>
                  ))}
                </TableRow>
              ))}
            </TableHeader>
            <TableBody>
              {rows.length ? (
                rows.map((row, index) => (
                  <TableRow
                    key={row.id}
                    id={`log-row-${row.id}`}
                    tabIndex={0}
                    aria-selected={row.id === selectedId}
                    data-state={row.id === selectedId ? 'selected' : undefined}
                    onClick={() =>
                      setSelectedId(row.id === selectedId ? null : row.id)
                    }
                    onKeyDown={(e) => onRowKeyDown(e, index)}
                    className={cn(
                      'cursor-pointer outline-none focus-visible:bg-muted/60',
                      row.original.level === 'error' &&
                        'bg-red-500/[0.04] dark:bg-red-500/[0.07]',
                    )}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell
                        key={cell.id}
                        className={cn(
                          'py-2',
                          // max-w-0 lets the message take the leftover width and truncate
                          cell.column.id === 'message' && 'max-w-0 min-w-32',
                        )}
                      >
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell
                    colSpan={table.getVisibleLeafColumns().length}
                    className="h-32 text-center"
                  >
                    <NoResults table={table} />
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>

        {selected && (
          <LogPanel
            row={selected}
            onPrevious={
              selectedIndex > 0 ? () => selectAt(selectedIndex - 1) : undefined
            }
            onNext={
              selectedIndex < rows.length - 1
                ? () => selectAt(selectedIndex + 1)
                : undefined
            }
            onClose={() => setSelectedId(null)}
          />
        )}
      </div>

      <LoadOlderEvents table={table} />
    </div>
  )
}

interface LogPanelProps {
  row: Row<LogEntry>
  onPrevious?: () => void
  onNext?: () => void
  onClose: () => void
}

function LogPanel({ row, onPrevious, onNext, onClose }: LogPanelProps) {
  const log = row.original
  return (
    <aside
      aria-label="Log details"
      onKeyDown={(e) => e.key === 'Escape' && onClose()}
      // Covers the table on phones, sits beside it from sm up
      className="absolute inset-0 z-10 bg-background sm:static sm:w-80 sm:shrink-0 sm:border-l"
    >
      <div className="sticky top-0">
        <div className="flex items-center gap-2 border-b py-1.5 pr-1.5 pl-4">
          <LevelLabel level={log.level} />
          <span className="text-sm text-muted-foreground tabular-nums">
            {formatDay(log.timestamp)} {formatTime(log.timestamp)}
          </span>
          <div className="ml-auto flex items-center">
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Previous event"
              disabled={!onPrevious}
              onClick={onPrevious}
            >
              <ChevronUp className="size-4" />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Next event"
              disabled={!onNext}
              onClick={onNext}
            >
              <ChevronDown className="size-4" />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Close details"
              onClick={onClose}
            >
              <X className="size-4" />
            </Button>
          </div>
        </div>

        <div className="space-y-4 p-4">
          <div className="space-y-1.5">
            <p className="text-base leading-snug font-medium">{log.message}</p>
            <p className="flex flex-wrap items-center gap-x-2 text-sm">
              <span
                className={cn(
                  'font-medium tabular-nums',
                  statusTone(log.status),
                )}
              >
                {log.status}
              </span>
              <span className="text-xs font-medium text-muted-foreground">
                {log.method}
              </span>
              <span className="break-all">{log.path}</span>
              <span className="text-muted-foreground">· {log.service}</span>
            </p>
          </div>
          <LogFields
            log={log}
            omit={['Level', 'Message', 'Method', 'Path', 'Status', 'Service']}
            className="border-t pt-4"
          />
        </div>
      </div>
    </aside>
  )
}

